mapper.select:
SELECT m.member_id,m.username,m.name,TO_CHAR(m.regdate,'yyyy-mm-dd') as dbday,a.authority,m.enabled FROM member m JOIN authority a ON m.member_id=a.member_id
AND authority=#{authority}
AND enabled=#{enabled}
ORDER BY m.member_id ASC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

SELECT COUNT(*)
FROM member m
JOIN authority a
ON m.member_id=a.member_id


		AND authority=#{authority}


		AND enabled=#{enabled}
